const projects = $input.all().map(item => item.json);

return [
  {
    json: {
      projects
    }
  }
];

const items = $input.all().map(item => item.json);

const profile = items.find(item => item.full_name);

const currentState = items.filter(item =>
  item.area &&
  !item.title
);

const activeGoals = items.filter(item =>
  item.title &&
  item.status === 'active'
);

return [
  {
    json: {
      profile: profile || null,
      current_state: currentState,
      active_goals: activeGoals
    }
  }
];

const decisions = $input.all().map(item => item.json);

return [
  {
    json: {
      project_decisions: decisions
    }
  }
];

const items = $input.all();

const memories = [];

for (const item of items) {
  const data = item.json;

  if (Array.isArray(data.memories)) {
    memories.push(...data.memories);
  }
}

return [
  {
    json: {
      memories
    }
  }
];

const messages = $input.all()
  .map(item => item.json)
  .filter(item => Object.keys(item).length > 0);

return [
  {
    json: {
      recent_messages: messages
    }
  }
];

const items = $input.all().map(item => item.json);

const context = {
  profile: null,
  current_state: [],
  active_goals: [],
  projects: [],
  project_decisions: [],
  memories: [],
  knowledge: [],
  recent_messages: []
};

for (const item of items) {
  if (!item || Object.keys(item).length === 0) continue;

  if (item.profile) context.profile = item.profile;
  if (item.current_state?.length) context.current_state = item.current_state;
  if (item.active_goals?.length) context.active_goals = item.active_goals;
  if (item.projects?.length) context.projects = item.projects;
  if (item.project_decisions?.length) context.project_decisions = item.project_decisions;
  if (item.memories?.length) context.memories = item.memories;
  if (Array.isArray(item.knowledge)) {
    context.knowledge = item.knowledge;
  }
  if (Array.isArray(item.recent_messages)) {
    context.recent_messages = item.recent_messages;
  }
}

return [{ json: context }];

